"use client";

import { Plus, Receipt, Trash2, X } from "lucide-react";
import { useState } from "react";

import { Field } from "~/components/shared/field";
import { MoneyText, useMoney } from "~/components/shared/money";
import { Badge } from "~/components/ui/badge";
import { Button } from "~/components/ui/button";
import { Dialog, DialogContent, DialogFooter } from "~/components/ui/dialog";
import { EmptyState } from "~/components/ui/empty-state";
import { Input } from "~/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "~/components/ui/select";
import { Skeleton } from "~/components/ui/skeleton";
import { toast } from "~/components/ui/toast";
import { minorUnitFactor } from "~/lib/money";
import { api } from "~/trpc/react";

export const INVOICE_BADGE: Record<
  string,
  "success" | "warning" | "danger" | "neutral" | "info"
> = {
  PAID: "success",
  PARTIAL: "warning",
  OVERDUE: "danger",
  SENT: "info",
  DRAFT: "neutral",
  VOID: "neutral",
};

interface DraftLine {
  description: string;
  quantity: number;
  unitPrice: number;
  productId?: string | null;
}

function InvoiceCreateDialog({
  open,
  onOpenChange,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}) {
  const utils = api.useUtils();
  const money = useMoney();
  const factor = minorUnitFactor(money.currency);
  const { data: companies } = api.company.list.useQuery({});
  const { data: products } = api.product.list.useQuery({ activeOnly: true });

  const [companyId, setCompanyId] = useState("");
  const [issueDate, setIssueDate] = useState(new Date().toISOString().slice(0, 10));
  const [dueDate, setDueDate] = useState("");
  const [lines, setLines] = useState<DraftLine[]>([
    { description: "", quantity: 1, unitPrice: 0 },
  ]);

  const create = api.accounting.createInvoice.useMutation();

  const subtotal = lines.reduce((s, l) => s + l.quantity * l.unitPrice, 0);

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!companyId) return toast.error("Pick a company first.");
    const validLines = lines.filter((l) => l.description.trim() && l.unitPrice > 0);
    if (!validLines.length) return toast.error("Add at least one line item.");
    try {
      await create.mutateAsync({
        companyId,
        issueDate: new Date(issueDate),
        dueDate: dueDate ? new Date(dueDate) : null,
        taxMinor: 0,
        lines: validLines.map((l) => ({
          description: l.description.trim(),
          quantity: l.quantity,
          unitPriceMinor: Math.round(l.unitPrice * factor),
          productId: l.productId ?? null,
        })),
      });
      toast.success("Draft invoice created");
      await utils.accounting.invalidate();
      onOpenChange(false);
      setLines([{ description: "", quantity: 1, unitPrice: 0 }]);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Could not create invoice");
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent title="New invoice" description="Created as a draft; issue it to post to the ledger." wide>
        <form onSubmit={onSubmit} className="space-y-4">
          <div className="grid gap-4 sm:grid-cols-3">
            <Field id="invCompany" label="Company" required>
              <Select value={companyId} onValueChange={setCompanyId}>
                <SelectTrigger id="invCompany">
                  <SelectValue placeholder="Select…" />
                </SelectTrigger>
                <SelectContent>
                  {companies?.map((c) => (
                    <SelectItem key={c.id} value={c.id}>
                      {c.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </Field>
            <Field id="invIssue" label="Issue date" required>
              <Input
                id="invIssue"
                type="date"
                value={issueDate}
                onChange={(e) => setIssueDate(e.target.value)}
              />
            </Field>
            <Field id="invDue" label="Due date">
              <Input
                id="invDue"
                type="date"
                value={dueDate}
                onChange={(e) => setDueDate(e.target.value)}
              />
            </Field>
          </div>

          <fieldset>
            <legend className="mb-1.5 text-sm font-medium text-ink-secondary">Line items</legend>
            <div className="space-y-2">
              {lines.map((line, i) => (
                <div key={i} className="flex items-center gap-2">
                  <Input
                    aria-label={`Line ${i + 1} description`}
                    placeholder="Description"
                    value={line.description}
                    onChange={(e) =>
                      setLines((ls) =>
                        ls.map((l, j) => (j === i ? { ...l, description: e.target.value } : l)),
                      )
                    }
                    className="flex-1"
                  />
                  <Input
                    aria-label={`Line ${i + 1} quantity`}
                    type="number"
                    min={0.01}
                    step={0.01}
                    value={line.quantity}
                    onChange={(e) =>
                      setLines((ls) =>
                        ls.map((l, j) =>
                          j === i ? { ...l, quantity: Number(e.target.value) } : l,
                        ),
                      )
                    }
                    className="w-20"
                  />
                  <Input
                    aria-label={`Line ${i + 1} unit price (${money.currency})`}
                    type="number"
                    min={0}
                    step={factor === 1 ? 1 : 0.01}
                    value={line.unitPrice}
                    onChange={(e) =>
                      setLines((ls) =>
                        ls.map((l, j) =>
                          j === i ? { ...l, unitPrice: Number(e.target.value) } : l,
                        ),
                      )
                    }
                    className="w-28"
                  />
                  <Button
                    variant="ghost"
                    size="iconSm"
                    aria-label={`Remove line ${i + 1}`}
                    disabled={lines.length === 1}
                    onClick={() => setLines((ls) => ls.filter((_, j) => j !== i))}
                  >
                    <X aria-hidden />
                  </Button>
                </div>
              ))}
            </div>
            <div className="mt-2 flex flex-wrap items-center gap-2">
              <Button
                variant="secondary"
                size="sm"
                onClick={() =>
                  setLines((ls) => [...ls, { description: "", quantity: 1, unitPrice: 0 }])
                }
              >
                <Plus aria-hidden />
                Add line
              </Button>
              {products?.length ? (
                <Select
                  value=""
                  onValueChange={(id) => {
                    const p = products.find((x) => x.id === id);
                    if (!p) return;
                    setLines((ls) => [
                      ...ls.filter((l) => l.description || l.unitPrice),
                      {
                        description: p.name,
                        quantity: 1,
                        unitPrice: p.unitPriceMinor / factor,
                        productId: p.id,
                      },
                    ]);
                  }}
                >
                  <SelectTrigger aria-label="Add a product" className="w-56">
                    <SelectValue placeholder="+ Add from product…" />
                  </SelectTrigger>
                  <SelectContent>
                    {products.map((p) => (
                      <SelectItem key={p.id} value={p.id}>
                        {p.name} · {money.format(p.unitPriceMinor, p.currencyCode)}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              ) : null}
            </div>
          </fieldset>

          <p className="text-end text-lg font-semibold text-ink">
            Total: <MoneyText minor={Math.round(subtotal * factor)} />
          </p>

          <DialogFooter>
            <Button variant="subtle" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" loading={create.isPending}>
              Create draft
            </Button>
          </DialogFooter>
        </form>
"use client";

import { HandCoins, Plus } from "lucide-react";
import { useState } from "react";

import { Field } from "~/components/shared/field";
import { MoneyText, useMoney } from "~/components/shared/money";
import { Button } from "~/components/ui/button";
import { Dialog, DialogContent, DialogFooter } from "~/components/ui/dialog";
import { EmptyState } from "~/components/ui/empty-state";
import { Input } from "~/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "~/components/ui/select";
import { Skeleton } from "~/components/ui/skeleton";
import { toast } from "~/components/ui/toast";
import { minorUnitFactor } from "~/lib/money";
import { paymentMethods } from "~/schemas/accounting";
import { api } from "~/trpc/react";

function PaymentCreateDialog({
  open,
  onOpenChange,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}) {
  const utils = api.useUtils();
  const money = useMoney();
  const factor = minorUnitFactor(money.currency);
  const { data: companies } = api.company.list.useQuery({});

  const [companyId, setCompanyId] = useState("");
  const [invoiceId, setInvoiceId] = useState("");
  const [amount, setAmount] = useState("");
  const [paidAt, setPaidAt] = useState(new Date().toISOString().slice(0, 10));
  const [method, setMethod] = useState<(typeof paymentMethods)[number]>("BANK");
  const [reference, setReference] = useState("");

  const { data: invoices } = api.accounting.invoices.useQuery(
    { companyId: companyId || undefined },
    { enabled: !!companyId },
  );
  const openInvoices = invoices?.filter((i) =>
    ["SENT", "PARTIAL", "OVERDUE"].includes(i.status),
  );

  const create = api.accounting.createPayment.useMutation();

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    const amountMinor = Math.round(parseFloat(amount) * factor);
    if (!companyId) return toast.error("Pick a company.");
    if (!amountMinor || amountMinor <= 0) return toast.error("Enter a positive amount.");
    try {
      await create.mutateAsync({
        companyId,
        invoiceId: invoiceId || null,
        amountMinor,
        paidAt: new Date(paidAt),
        method,
        reference: reference || null,
      });
      toast.success("Payment recorded — posted DR Bank / CR Accounts Receivable");
      await utils.accounting.invalidate();
      await utils.dashboard.invalidate();
      onOpenChange(false);
      setAmount("");
      setReference("");
      setInvoiceId("");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Could not record payment");
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent title="Record payment" description="Money received from a client.">
        <form onSubmit={onSubmit} className="grid gap-4 sm:grid-cols-2">
          <Field id="payCompany" label="Company" required>
            <Select
              value={companyId}
              onValueChange={(v) => {
                setCompanyId(v);
                setInvoiceId("");
              }}
            >
              <SelectTrigger id="payCompany">
                <SelectValue placeholder="Select…" />
              </SelectTrigger>
              <SelectContent>
                {companies?.map((c) => (
                  <SelectItem key={c.id} value={c.id}>
                    {c.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </Field>

          <Field id="payInvoice" label="Applies to invoice">
            <Select
              value={invoiceId}
              onValueChange={(v) => setInvoiceId(v === "none" ? "" : v)}
            >
              <SelectTrigger id="payInvoice" disabled={!companyId}>
                <SelectValue placeholder="No specific invoice" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="none">No specific invoice</SelectItem>
                {openInvoices?.map((i) => (
                  <SelectItem key={i.id} value={i.id}>
                    {i.invoiceNumber}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </Field>

          <Field id="payAmount" label={`Amount (${money.currency})`} required>
            <Input
              id="payAmount"
              type="number"
              min={0}
              step={factor === 1 ? 1 : 0.01}
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
            />
          </Field>
          <Field id="payDate" label="Paid on" required>
            <Input
              id="payDate"
              type="date"
              value={paidAt}
              onChange={(e) => setPaidAt(e.target.value)}
            />
          </Field>

          <Field id="payMethod" label="Method">
            <Select value={method} onValueChange={(v) => setMethod(v as typeof method)}>
              <SelectTrigger id="payMethod">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {paymentMethods.map((m) => (
                  <SelectItem key={m} value={m}>
                    {m.toLowerCase()}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </Field>
          <Field id="payRef" label="Reference">
            <Input
              id="payRef"
              value={reference}
              onChange={(e) => setReference(e.target.value)}
              placeholder="Transfer id…"
            />
          </Field>

          <DialogFooter className="sm:col-span-2">
            <Button variant="subtle" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" loading={create.isPending}>
              Record payment
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

export function PaymentsTab() {
  const { data: payments, isLoading } = api.accounting.payments.useQuery({ take: 100 });
  const [createOpen, setCreateOpen] = useState(false);

  if (isLoading) return <Skeleton className="h-96" />;

  return (
