      ) : (
        <div className="glass-card overflow-x-auto">
          <table className="w-full min-w-[560px] text-md">
            <thead>
              <tr className="border-b border-line text-sm text-ink-subtle">
                <th scope="col" className="px-4 py-2.5 text-start font-medium">
