 async function select(id,name){await page.locator('#'+id).click();await page.getByRole('option',{name,exact:true}).click();}
 async function invoice(company,description,price,file){
  await page.getByRole('tab',{name:'Invoices',exact:true}).click();
  await page.getByRole('button',{name:'New invoice',exact:true}).click();
  await select('invCompany',company);
  await page.getByLabel('Line 1 description',{exact:true}).fill(description);
  await page.getByLabel(/Line 1 unit price/).fill(price);
  await page.getByRole('button',{name:'Create draft',exact:true}).click();
  await page.getByRole('dialog').waitFor({state:'hidden'});
  const row=page.getByRole('row').filter({hasText:company});await row.getByRole('button',{name:'Issue',exact:true}).click();
