 }
 await invoice('Hoa Sen Trading MLD','Website maintenance','12345','tc-01-vnd-invoice.png');
 await page.getByRole('tab',{name:'Payments',exact:true}).click();
 await page.getByRole('button',{name:'Record payment',exact:true}).click();
 await select('payCompany','Hoa Sen Trading MLD');await page.locator('#payInvoice').click();
 const options=page.getByRole('option');await options.last().click();await page.locator('#payAmount').fill('5000');
