 await page.waitForTimeout(1000);await page.screenshot({path:'../answers/BUG-02/evidence/tc-02-vnd-payment.png',fullPage:true});
 await invoice('Pine Labs MLD','Consulting','123.45','tc-03-usd-invoice.png');
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

